function scoutRenderSaved(){const box=$('scout-saved-list');if(!box)return;const arr=scoutingMatches.slice().sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));box.innerHTML=arr.length?arr.map(m=>{const sc=scoutSetsScore(m),active=Number(m.id)===Number(scoutingActiveId);return `<div class="scout-saved-item"><div><strong>${esc(m.opponent)} · ${sc.us}–${sc.opponent} sets ${active?'· ACTIVO':''}</strong><small>${esc(m.date)}${m.competition?' · '+esc(m.competition):''} · ${m.status==='finished'?'Finalizado':'En curso'} · ${scoutActionCount(m)} acciones</small></div><div class="scout-saved-actions"><button class="ghost" onclick="scoutOpenSaved(${m.id})">Abrir</button><button class="ghost download" onclick="scoutExportPDF(${m.id})">PDF</button><button class="ghost download" onclick="scoutExportCSV(${m.id})">CSV</button><button class="danger" onclick="scoutDeleteSaved(${m.id})">Eliminar</button></div></div>`}).join(''):'<div class="scout-action-empty">No hay partidos de scouting guardados.</div>'}
