const VC_POS_META={p1:{zone:'Z1',line:'Zaguero',serve:true},p2:{zone:'Z2',line:'Delantero'},p3:{zone:'Z3',line:'Delantero'},p4:{zone:'Z4',line:'Delantero'},p5:{zone:'Z5',line:'Zaguero'},p6:{zone:'Z6',line:'Zaguero'}};
